import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Anomalies() {
    const navigate = useNavigate();
    const [anomalies, setAnomalies] = useState([]);

    useEffect(() => {
        fetch('http://localhost:8000/api/anomalies/')
            .then(res => res.json())
            .then(data => setAnomalies(data))
            .catch(err => console.error('Error:', err));
    }, []);

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <h1>📋 لیست آنومالی‌ها</h1>
                <button
                    onClick={() => navigate('/anomalies/new')}
                    style={{
                        padding: '10px 20px',
                        backgroundColor: '#1976d2',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                    }}
                >
                    + ثبت آنومالی جدید
                </button>
            </div>
            <table style={{ width: '100%', borderCollapse: 'collapse', backgroundColor: 'white', borderRadius: '8px' }}>
                <thead>
                    <tr style={{ backgroundColor: '#f5f5f5' }}>
                        <th style={{ padding: '12px', textAlign: 'right' }}>عنوان</th>
                        <th style={{ padding: '12px', textAlign: 'right' }}>مکان</th>
                        <th style={{ padding: '12px', textAlign: 'right' }}>سطح ریسک</th>
                        <th style={{ padding: '12px', textAlign: 'right' }}>وضعیت</th>
                    </tr>
                </thead>
                <tbody>
                    {anomalies.length === 0 ? (
                        <tr>
                            <td colSpan="4" style={{ textAlign: 'center', padding: '20px', color: '#666' }}>
                                هیچ آنومالی ثبت نشده است
                            </td>
                        </tr>
                    ) : (
                        anomalies.map((anomaly) => (
                            <tr key={anomaly.id} style={{ borderBottom: '1px solid #eee' }}>
                                <td style={{ padding: '12px' }}>{anomaly.title}</td>
                                <td style={{ padding: '12px' }}>{anomaly.location}</td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '4px 12px',
                                        borderRadius: '12px',
                                        backgroundColor: anomaly.risk_level === 'critical' ? '#ffebee' : '#fff3e0',
                                        color: anomaly.risk_level === 'critical' ? '#c62828' : '#e65100'
                                    }}>
                                        {anomaly.risk_level}
                                    </span>
                                </td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '4px 12px',
                                        borderRadius: '12px',
                                        backgroundColor: '#e3f2fd',
                                        color: '#0d47a1'
                                    }}>
                                        {anomaly.status}
                                    </span>
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
    );
}

export default Anomalies;
